const block = (...sections) => sections.map(s => s.filter(Boolean).join('\n')).filter(Boolean).join('\n\n');
const quoteText = (cfg, total, load, extrasText, refused) => block(
  ['Thanks for the photos! Our price to haul it away is ' + money(total) + (load ? ' (' + String(load).toLowerCase() + (extrasText ? ', plus ' + extrasText : '') + ')' : '') + '.', refused ? 'We are not able to take: ' + refused + '.' : ''],
  ['Reply YES and a day that works, like "YES Saturday", to book. Good for ' + cfg.quote_valid_days + ' days.', cfg.business_name]);
