} else if (q.status === 'owner_review') {
  texts.push({ to: k.from, body: 'Thanks. We are looking at your photos now and will text your price shortly.\n' + cfg.business_name });
  texts.push({ to: cfg.owner_cell, body: pretty(k.from) + ' (' + tag(q.quote_id) + ', waiting on you) says:\n' + k.body });
} else if (q.status === 'sent') {
  texts.push({ to: k.from, body: (address ? 'Got the address. ' : '') + 'Your price is ' + money(num(q.total, 0)) + '. Reply YES and a day (like "YES Saturday") to book' + (address ? '.' : ', and include the address.') + ' If something changed, send new photos.\n' + cfg.business_name });
  if (!address) texts.push({ to: cfg.owner_cell, body: pretty(k.from) + ' (' + tag(q.quote_id) + ', quoted ' + money(num(q.total, 0)) + ') asks:\n' + k.body });
}
return [{ json: { texts, update, save: !!update } }];

// Every half hour: reminds you about quotes waiting on your OK, nudges a customer once if a sent
// quote has gone quiet, and expires quotes past their valid days (quietly, no text).
const ran = name => { try { return $(name).isExecuted; } catch (e) { return false; } };
const num = (v, d) => { if (v === '' || v === null || v === undefined) return d; const n = Number(String(v).replace(/[$,\s]/g, '')); return isNaN(n) ? d : n; };
const round2 = n => Math.round((n + Number.EPSILON) * 100) / 100;
const money = n => '$' + (Math.round(n) === n ? String(n) : n.toFixed(2));
const norm = v => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const digits = v => String(v || '').replace(/[^\d+]/g, '');
const samePhone = (a, b) => { const x = digits(a).replace(/^\+?1(?=\d{10}$)/, ''), y = digits(b).replace(/^\+?1(?=\d{10}$)/, ''); return !!x && x === y; };
const looksLikeAddress = t => /\b\d{1,6}\s+[A-Za-z0-9.'-]+(\s+[A-Za-z0-9.'-]+){0,4}\s+(st|street|ave|avenue|rd|road|dr|drive|ln|lane|ct|court|blvd|way|pl|place|cir|circle|trl|trail|pkwy|hwy|ter|terrace)\b/i.test(String(t || ''));
const addressFrom = t => looksLikeAddress(t) ? String(t).match(/\b\d{1,6}\s+[A-Za-z].*$/s)[0].replace(/\s+/g, ' ').trim().slice(0, 200) : '';
const e164 = v => { const d = String(v || '').replace(/\D/g, ''); return d ? '+' + (d.length === 10 ? '1' + d : d) : ''; };
const pretty = v => { const d = String(v || '').replace(/\D/g, '').replace(/^1(?=\d{10}$)/, ''); return d.length === 10 ? '(' + d.slice(0, 3) + ') ' + d.slice(3, 6) + '-' + d.slice(6) : String(v || ''); };
const tag = id => '#' + String(id || '').replace(/\D/g, '').slice(-4);
const block = (...sections) => sections.map(s => s.filter(Boolean).join('\n')).filter(Boolean).join('\n\n');
const quoteText = (cfg, total, load, extrasText, refused) => block(
  ['Thanks for the photos! Our price to haul it away is ' + money(total) + (load ? ' (' + String(load).toLowerCase() + (extrasText ? ', plus ' + extrasText : '') + ')' : '') + '.', refused ? 'We are not able to take: ' + refused + '.' : ''],
  ['Reply YES and a day that works, like "YES Saturday", to book. Good for ' + cfg.quote_valid_days + ' days.', cfg.business_name]);
const OPEN = ['owner_review', 'sent'];
const cfg = $('Read your settings').first().json.cfg;
const rows = $('Read all quotes').all().map(i => i.json).filter(q => q.quote_id);
const now = DateTime.now().setZone(cfg.timezone);
const hours = iso => { const d = DateTime.fromISO(String(iso || '')); return d.isValid ? now.diff(d, 'hours').hours : null; };
const updates = [], texts = [];
const waitingCount = rows.filter(q => q.status === 'owner_review').length;
const latestByPhone = {};
rows.forEach(q => { const k = digits(q.phone); if (!latestByPhone[k] || String(q.created_at) > String(latestByPhone[k].created_at)) latestByPhone[k] = q; });
for (const q of rows) {
  const age = hours(q.created_at);
  if (age === null) continue;
  if (q.status === 'owner_review') {
    const n = num(q.owner_reminders, 0);
    if (age >= 1 && n < 3 && age >= 1 + 4 * n) {
      updates.push({ quote_id: q.quote_id, owner_reminders: n + 1 });
      texts.push({ to: cfg.owner_cell, body: 'Still waiting on you: ' + tag(q.quote_id) + ' ' + (q.address || pretty(q.phone)) + ', ' + money(num(q.total, 0)) + (q.approval_reasons ? ' (' + q.approval_reasons + ')' : '') + '.\nReply YES, NO or a price' + (waitingCount > 1 ? ', with the number, like "YES ' + tag(q.quote_id).slice(1) + '"' : '') + '.' });
    }
  } else if (q.status === 'sent') {
    const sentAge = hours(q.sent_at) ?? age;
    if (age >= cfg.quote_valid_days * 24) { updates.push({ quote_id: q.quote_id, status: 'expired', closed_at: now.toISO() }); continue; }
    if (sentAge >= cfg.nudge_after_hours && num(q.nudges, 0) === 0 && latestByPhone[digits(q.phone)] === q && now.hour >= 9 && now.hour < 19) {
      updates.push({ quote_id: q.quote_id, nudges: 1 });
      texts.push({ to: e164(q.phone), body: 'Hi, just checking in on the ' + money(num(q.total, 0)) + ' quote to haul your stuff away. Reply YES and a day that works to book, or STOP if you are all set.\n' + cfg.business_name });
    }
  }
}
return [{ json: { updates, texts, checked: rows.length } }];

